import type {
  DropdownIconButtonProps,
  DropdownIconButtonDropdownIconProps,
  DropdownIconButtonMenuContentProps,
  DropdownIconButtonMenuItemProps,
} from "./dropdown-icon-button.types";

import React, { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { ChevronDownSm } from "@exp-textura/icons";
import { Menu } from "@components/menu";

import { DropdownIconButtonClasses, StyledDropdownIconButton } from "./dropdown-icon-button.styles";

const getDropdownIconButtonChildren = (
  children: React.ReactNode,
): {
  dropdownIcon: React.ReactElement | null;
  menuContent: React.ReactElement | null;
  iconContent: React.ReactNode[];
} => {
  let dropdownIcon: React.ReactElement | null = null;
  let menuContent: React.ReactElement | null = null;
  const iconContent: React.ReactNode[] = [];

  React.Children.forEach(children, (child) => {
    if (React.isValidElement(child)) {
      const displayName = (child.type as { displayName?: string }).displayName;
      if (displayName === DropdownIconButtonDropdownIcon.displayName) {
        dropdownIcon = child;
      } else if (displayName === DropdownIconButtonMenuContent.displayName) {
        menuContent = child;
      } else {
        iconContent.push(child);
      }
    } else if (child !== null && child !== undefined && child !== false && child !== true) {
      iconContent.push(child);
    }
  });

  return { dropdownIcon, menuContent, iconContent };
};

const DropdownIconButtonRoot = forwardRef<HTMLButtonElement, DropdownIconButtonProps>(
  (
    {
      children,
      className,
      variant = "default",
      size = "default",
      disabled = false,
      selected = false,
      side = "bottom",
      sideOffset = 4,
      align = "end",
      alignOffset = 0,
      menuVariant = "icons-only",
      ...props
    },
    ref,
  ) => {
    const theme = useTheme();
    const rootClasses = clsx(DropdownIconButtonClasses.root, className, {
      [DropdownIconButtonClasses.sm]: size === "sm",
    });

    const { dropdownIcon, menuContent, iconContent } = getDropdownIconButtonChildren(children);

    const dropdownIndicator = dropdownIcon ? (
      React.cloneElement(dropdownIcon as React.ReactElement, {
        className: clsx(
          (dropdownIcon as React.ReactElement).props.className,
          DropdownIconButtonClasses.dropdownIcon,
        ),
      })
    ) : (
      <ChevronDownSm aria-hidden="true" className={DropdownIconButtonClasses.dropdownIcon} />
    );

    const iconContentWithClasses = React.Children.map(iconContent, (child) => {
      if (React.isValidElement(child)) {
        return React.cloneElement(child as React.ReactElement, {
          className: clsx(
            (child as React.ReactElement).props.className,
            DropdownIconButtonClasses.leadingIcon,
          ),
        });
      }
      return child;
    });

    const menuContentWithProps = menuContent && <Menu.Content {...menuContent.props} />;

    return (
      <Menu
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
        variant={menuVariant}
      >
        <Menu.Trigger>
          <StyledDropdownIconButton
            ref={ref}
            className={rootClasses}
            currentTheme={theme}
            data-selected={selected ? "true" : undefined}
            disabled={disabled}
            variant={variant}
            {...props}
          >
            {iconContentWithClasses}
            {dropdownIndicator}
          </StyledDropdownIconButton>
        </Menu.Trigger>
        {menuContentWithProps}
      </Menu>
    );
  },
);
DropdownIconButtonRoot.displayName = "DropdownIconButton";

const DropdownIconButtonDropdownIcon = ({ children }: DropdownIconButtonDropdownIconProps) => {
  return <>{children}</>;
};
DropdownIconButtonDropdownIcon.displayName = "DropdownIconButton.DropdownIcon";

const DropdownIconButtonMenuContent = (props: DropdownIconButtonMenuContentProps) => {
  // Placeholder wrapper for menu content props. Rendering happens in DropdownIconButtonRoot.
  return <>{props.children}</>;
};
DropdownIconButtonMenuContent.displayName = "DropdownIconButton.MenuContent";

const DropdownIconButtonMenuItem = forwardRef<HTMLDivElement, DropdownIconButtonMenuItemProps>(
  ({ children, ...props }, ref) => {
    return (
      <Menu.Item ref={ref} {...props}>
        {children}
      </Menu.Item>
    );
  },
);
DropdownIconButtonMenuItem.displayName = "DropdownIconButton.MenuItem";

const DropdownIconButton = Object.assign(DropdownIconButtonRoot, {
  DropdownIcon: DropdownIconButtonDropdownIcon,
  MenuContent: DropdownIconButtonMenuContent,
  MenuItem: DropdownIconButtonMenuItem,
});

export default DropdownIconButton;
